try{
  ClipboardPage Primary = tools.getPrimaryPage();
  ClipboardPage satu = tools.findPage("ImageSalvage.ClaimData");
  ClipboardProperty claimno = satu.getProperty(".City");
  ClipboardPage temp2 = tools.findPage("InsertImageSalvage.ClaimData.Lelang");
  ClipboardProperty temp_attach = temp2.getProperty(".AttachStream");
  ClipboardProperty code = temp2.getProperty(".Code");
  ClipboardProperty numberss = temp2.getProperty(".pyLineNumber");
  String attch = temp_attach.toString().replaceAll("\n", "");
  String data_s = "{\"AttachStream\":\""+attch+"\",\"pyLineNumber\":\""+numberss.toString() +"\",\"Code\":\""+code.toString()+"\"}";
  claimno.setValue(data_s);

} catch(Exception e){
  oLog.error("ReloadSection:Expection : "+e.getMessage());
}
